#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const int MOD = 10007;

    string s;
    if (!getline(cin, s)) return 0;

    int n = (int)s.size() / 5;          // 因子个数，每个 '(t+d)' 长度为5
    vector<int> a(n);

    // 解析每个因子 (t+d) 或 (t-d)
    for (int k = 0; k < n; ++k) {
        int base = 5 * k;
        char op = s[base + 2];          // '+' 或 '-'
        int d = s[base + 3] - '0';      // 数字 1..9
        int val = (op == '-') ? -d : d;
        // 映射到 [0, MOD) 区间
        a[k] = (val % MOD + MOD) % MOD;
    }

    // 前缀积 L[i] = a[0] * ... * a[i-1] (mod MOD), L[0]=1
    vector<int> L(n, 1), R(n, 1);
    for (int i = 1; i < n; ++i) {
        L[i] = (int)((1LL * L[i - 1] * a[i - 1]) % MOD);
    }

    // 后缀积 R[i] = a[i+1] * ... * a[n-1] (mod MOD), R[n-1]=1
    for (int i = n - 2; i >= 0; --i) {
        R[i] = (int)((1LL * R[i + 1] * a[i + 1]) % MOD);
    }

    // 求和
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        ans += 1LL * L[i] * R[i] % MOD;
        if (ans >= (1LL << 60)) ans %= MOD;  // 防止长整数溢出
    }
    ans = (ans % MOD + MOD) % MOD;
    cout << ans << "\n";

    return 0;
}
